sql:
SELECT 
    (SELECT COUNT(*) FROM gasstations WHERE Country = 'Czech Republic' AND Segment = 'discount') -
    (SELECT COUNT(*) FROM gasstations WHERE Country = 'Slovakia' AND Segment = 'discount') AS Difference;

SELECT notes
FROM event
WHERE event_date = '2019-09-14' AND type = 'fundraising';

SELECT SUM(cost) AS total_cost
FROM expense
WHERE expense_description LIKE '%Pizza%';

SELECT SUM(cost) AS total_expense
FROM expense
WHERE expense_date = '2019-08-20';

SELECT COUNT(*) 
FROM Player_Attributes 
WHERE preferred_foot = 'left';

SELECT player_name
FROM Player
WHERE height = (SELECT MAX(height) FROM Player);

SELECT id 
FROM publisher 
WHERE publisher_name = 'Star Trek';

SELECT COUNT(*) 
FROM users 
WHERE LastAccessDate > '2014-09-01';

SELECT COUNT(*) 
FROM circuits 
WHERE location = 'Adelaide' AND country = 'Australia';

SELECT DisplayName
FROM users
WHERE strftime('%Y', CreationDate) = '2011';

SELECT LastEditorDisplayName
FROM posts
WHERE Title = 'Examples for teaching: Correlation does not mean causation';
